INSERT INTO titles (id, name, kind, year, genre, maturity_rating, rating, synopsis, poster, backdrop, video_url, duration, top10_rank, language) VALUES
  (1, 'Disclosure Day', 'movie', '2026', 'Science Fiction', 'TV-14', 6.7, 'A cybersecurity expert becomes a whistleblower after uncovering secrets about aliens, putting him on the run from a corporation. Meanwhile, a meteorologist experiencing strange phenomena joins forces with him to prove there''s life beyond our understanding.', '/assets/posters/movie_1275779.jpg', '/assets/backdrops/movie_1275779.jpg', '/assets/video/clip_30070091.mp4', 103, 3, 'en'),
  (2, 'The Odyssey', 'movie', '2026', 'Adventure', 'TV-14', 7.9, 'Odysseus, the legendary King of Ithaca, embarks on a long and perilous journey home following the Trojan War. Throughout his voyage, he is forced to confront the whims of gods, mythological monsters, and trials that stretch both his cunning and his humanity to the breaking point.', '/assets/posters/movie_1368337.jpg', '/assets/backdrops/movie_1368337.jpg', '/assets/video/clip_18972999.mp4', 110, 1, 'en'),
  (3, 'Backrooms', 'movie', '2026', 'Horror', 'TV-14', 7.1, 'A strange doorway appears in the basement of a furniture showroom.', '/assets/posters/movie_1083381.jpg', '/assets/backdrops/movie_1083381.jpg', '/assets/video/clip_27152549.mp4', 117, NULL, 'en'),
  (4, 'Scary Movie', 'movie', '2026', 'Comedy', 'TV-14', 6.3, 'Twenty-six years after outrunning a suspiciously familiar masked killer, the Core Four are back in the killer''s crosshairs and no horror movie IP is safe.', '/assets/posters/movie_1273221.jpg', '/assets/backdrops/movie_1273221.jpg', '/assets/video/clip_27152555.mp4', 124, NULL, 'en'),
  (5, 'The Mandalorian and Grogu', 'movie', '2026', 'Fantasy', 'TV-14', 6.7, 'The evil Empire has fallen, and Imperial warlords remain scattered throughout the galaxy. As the fledgling New Republic works to protect everything the Rebellion fought for, they have enlisted the help of legendary Mandalorian bounty hunter Din Djarin and his young apprentice Grogu.', '/assets/posters/movie_1228710.jpg', '/assets/backdrops/movie_1228710.jpg', '/assets/video/clip_30997958.mp4', 96, 6, 'en'),
  (6, 'Obsession', 'movie', '2026', 'Horror', 'TV-14', 8.2, 'After breaking the mysterious "One Wish Willow" to win his crush''s heart, a hopeless romantic finds himself getting exactly what he asked for but soon discovers that some desires come at a dark, sinister price.', '/assets/posters/movie_1339713.jpg', '/assets/backdrops/movie_1339713.jpg', '/assets/video/clip_35079542.mp4', 103, NULL, 'en'),
  (7, 'Spider-Man: Brand New Day', 'movie', '2026', 'Science Fiction', 'TV-14', 0, 'Fighting crime full-time as Spider-Man in a world that doesn''t remember him—and the pressure of seeing his old friends move on without him—sparks a change in Peter Parker he may not have the power to control. But that transformation might also be the only thing that can stop a shocking new threat to the city and those he loves - a powerful villain no one can even see.', '/assets/posters/movie_969681.jpg', '/assets/backdrops/movie_969681.jpg', '/assets/video/clip_30070091.mp4', 110, 4, 'en'),
  (8, 'Descendants: Wicked Wonderland', 'movie', '2026', 'Fantasy', 'TV-14', 7.8, 'Now that the Queen of Hearts is nice and Cinderella is safe, things seem perfect for Red and Chloe… But little do they know that changing the past created a new villain — Maddox Hatter. When Maddox captures the Queen of Hearts, Red and Chloe must work alongside Red’s new sister Pink, Luisa Madrigal’s son Luis, and Maddox’s son Max to save her and Wonderland.', '/assets/posters/movie_1318621.jpg', '/assets/backdrops/movie_1318621.jpg', '/assets/video/clip_18972999.mp4', 117, NULL, 'en'),
  (9, 'The Death of Robin Hood', 'movie', '2026', 'Adventure', 'TV-14', 6.7, 'Grappling with his past after a life of crime and murder, Robin Hood finds himself gravely injured after a battle he thought would be his last. In the hands of a mysterious woman, he is offered a chance at salvation.', '/assets/posters/movie_1284465.jpg', '/assets/backdrops/movie_1284465.jpg', '/assets/video/clip_27152549.mp4', 124, NULL, 'en'),
  (10, 'Moana', 'movie', '2026', 'Family', 'TV-14', 5.8, 'Teenage Moana answers the Ocean''s call and, for the first time, voyages beyond the reef of her island of Motunui with infamous demigod Maui on an unforgettable journey to restore prosperity to her people.', '/assets/posters/movie_1108427.jpg', '/assets/backdrops/movie_1108427.jpg', '/assets/video/clip_27152555.mp4', 96, 9, 'en'),
  (11, 'Avengers: Doomsday', 'movie', '2026', 'Science Fiction', 'TV-14', 0, 'Beloved heroes from three distinct universes are set on a deadly collision course and face an existential threat unlike anything they''ve ever encountered.', '/assets/posters/movie_1003596.jpg', '/assets/backdrops/movie_1003596.jpg', '/assets/video/clip_30997958.mp4', 103, 2, 'en'),
  (12, 'The Furious', 'movie', '2026', 'Action', 'TV-14', 7.4, 'After a criminal network kidnaps Wang Wei''s daughter and the corrupt police refuse to assist him, Wei sets out on his own to locate her. Navin, a tenacious journalist whose wife has mysteriously vanished, is his only ally. In this explosive martial arts showdown, the unlikely duo fights the kidnappers ruthlessly driven by a furious vengeance.', '/assets/posters/movie_1280738.jpg', '/assets/backdrops/movie_1280738.jpg', '/assets/video/clip_35079542.mp4', 110, NULL, 'zh'),
  (13, 'Other Mommy', 'movie', '2026', 'Horror', 'TV-14', 0, 'A young girl, her family and their home are haunted by a sinister entity that is determined to take up residence inside her. But first, it needs to persuade her to let it in…', '/assets/posters/movie_1400837.jpg', '/assets/backdrops/movie_1400837.jpg', '/assets/video/clip_30070091.mp4', 117, NULL, 'en'),
  (14, 'Heartstopper Forever', 'movie', '2026', 'Romance', 'TV-14', 6.9, 'It''s a new school year for the Truham-Higgs gang. As Nick and Charlie''s relationship deepens, their thoughts turn to life after the last bell rings.', '/assets/posters/movie_1468683.jpg', '/assets/backdrops/movie_1468683.jpg', '/assets/video/clip_18972999.mp4', 124, NULL, 'en'),
  (15, 'Toy Story 5', 'movie', '2026', 'Animation', 'TV-14', 7.4, 'When Bonnie receives a Lilypad tablet as a gift and becomes obsessed, Buzz, Woody, Jessie and the rest of the gang''s jobs become exponentially harder when they have to go head to head with the all-new threat to playtime.', '/assets/posters/movie_1084244.jpg', '/assets/backdrops/movie_1084244.jpg', '/assets/video/clip_27152549.mp4', 96, 7, 'en'),
  (16, 'Evil Dead Burn', 'movie', '2026', 'Horror', 'TV-14', 6.7, 'After her husband''s abrupt death, Alice seeks solace with his remaining family — descendants of a leading researcher on demonic possession. As her in-laws transform one by one into creatures that feed on fear, she comes to discover that the vows she took in life survive even in death.', '/assets/posters/movie_1212763.jpg', '/assets/backdrops/movie_1212763.jpg', '/assets/video/clip_27152555.mp4', 103, NULL, 'en'),
  (17, 'The Breadwinner', 'movie', '2026', 'Comedy', 'TV-14', 6.9, 'After his wife Katie lands a once-in-a-lifetime deal on Shark Tank that takes her on a prolonged business trip - lifelong breadwinner Nate Wilcox now has to fend for his family as a first-time stay-at-home dad.', '/assets/posters/movie_1440050.jpg', '/assets/backdrops/movie_1440050.jpg', '/assets/video/clip_30997958.mp4', 110, NULL, 'en'),
  (18, 'Mortal Kombat II', 'movie', '2026', 'Action', 'TV-14', 8.0, 'The fan favorite champions—now joined by Johnny Cage himself—are pitted against one another in the ultimate, no-holds barred, gory battle to defeat the dark rule of Shao Kahn that threatens the very existence of the Earthrealm and its defenders.', '/assets/posters/movie_931285.jpg', '/assets/backdrops/movie_931285.jpg', '/assets/video/clip_35079542.mp4', 117, 8, 'en'),
  (19, 'Minions & Monsters', 'movie', '2026', 'Adventure', 'TV-14', 6.4, 'This is the rambunctious, ridiculous and totally true story of how the Minions conquered Hollywood, became movie stars, lost everything, unleashed monsters onto the world and then banded together to try and save the planet from the mayhem they had just created.', '/assets/posters/movie_1315772.jpg', '/assets/backdrops/movie_1315772.jpg', '/assets/video/clip_30070091.mp4', 124, NULL, 'en'),
  (20, 'The Devil Wears Prada 2', 'movie', '2026', 'Comedy', 'TV-14', 7.1, 'Andy Sachs returns to Runway as Miranda Priestly navigates a new media landscape and Runway''s position within. The duo reconnect with former assistant Emily Charlton, now the head of a luxury brand that possesses funding which could ensure Runway''s survival.', '/assets/posters/movie_1314481.jpg', '/assets/backdrops/movie_1314481.jpg', '/assets/video/clip_18972999.mp4', 96, NULL, 'en'),
  (21, 'The East Palace', 'series', '2026', 'Mystery', 'TV-14', 8.0, 'A man who walks the spirit world and a court lady who hears the dead enter the East Palace by the king''s orders — can they unravel its dark secrets?', '/assets/posters/tv_279323.jpg', '/assets/backdrops/tv_279323.jpg', '/assets/video/clip_27152549.mp4', 42, NULL, 'ko'),
  (22, 'House of the Dragon', 'series', '2022', 'Sci-Fi & Fantasy', 'TV-14', 8.4, 'The Targaryen dynasty is at the absolute apex of its power, with more than 15 dragons under their yoke. Most empires crumble from such heights. In the case of the Targaryens, their slow fall begins when King Viserys breaks with a century of tradition by naming his daughter Rhaenyra heir to the Iron Throne. But when Viserys later fathers a son, the court is shocked when Rhaenyra retains her status as his heir, and seeds of division sow friction across the realm.', '/assets/posters/tv_94997.jpg', '/assets/backdrops/tv_94997.jpg', '/assets/video/clip_27152555.mp4', 42, 2, 'en'),
  (23, 'Lucky', 'series', '2026', 'Drama', 'TV-14', 6.8, 'When a multi-million-dollar heist goes sideways, con artist Lucky is forced to go on the run. Pursued by both the FBI and a ruthless crime boss, Lucky must fight for her life—and a way out.', '/assets/posters/tv_278624.jpg', '/assets/backdrops/tv_278624.jpg', '/assets/video/clip_30997958.mp4', 42, 9, 'en'),
  (24, 'Silo', 'series', '2023', 'Sci-Fi & Fantasy', 'TV-14', 8.2, 'In a ruined and toxic future, thousands live in a giant silo deep underground. After its sheriff breaks a cardinal rule and residents die mysteriously, engineer Juliette starts to uncover shocking secrets and the truth about the silo.', '/assets/posters/tv_125988.jpg', '/assets/backdrops/tv_125988.jpg', '/assets/video/clip_35079542.mp4', 42, 4, 'en'),
  (25, 'Rick and Morty', 'series', '2013', 'Animation', 'TV-14', 8.7, 'Follows a sociopathic genius scientist who drags his inherently timid grandson on adventures across the universe.', '/assets/posters/tv_60625.jpg', '/assets/backdrops/tv_60625.jpg', '/assets/video/clip_30070091.mp4', 42, 5, 'en'),
  (26, 'One Piece', 'series', '1999', 'Action & Adventure', 'TV-14', 8.7, 'Years ago, the fearsome Pirate King, Gol D. Roger was executed leaving a huge pile of treasure and the famous "One Piece" behind. Whoever claims the "One Piece" will be named the new King of the Pirates.
