  (27, 'Agent Kim Reactivated', 'series', '2026', 'Action & Adventure', 'TV-14', 7.2, 'When an unassuming dad''s daughter goes missing, he dusts off his old black-ops skills to track her down — only to attract the wrong kind of attention.', '/assets/posters/tv_296206.jpg', '/assets/backdrops/tv_296206.jpg', '/assets/video/clip_27152549.mp4', 42, 10, 'ko'),
  (28, 'The Hawk', 'series', '2026', 'Comedy', 'TV-14', 5.0, 'On the back nine of his career, golf legend Lonnie "The Hawk" Hawkins chases one final major — and drags everyone he loves into the chaos.', '/assets/posters/tv_254528.jpg', '/assets/backdrops/tv_254528.jpg', '/assets/video/clip_27152555.mp4', 42, 1, 'en'),
  (29, 'Spooky in Love', 'series', '2026', 'Comedy', 'TV-14', 9.2, 'When a ghost-seeing heir and an ace prosecutor learn that a single touch makes them a strangely effective duo, they team up to crack unsolved murders.', '/assets/posters/tv_298610.jpg', '/assets/backdrops/tv_298610.jpg', '/assets/video/clip_30997958.mp4', 42, NULL, 'ko'),
  (30, 'Ride or Die', 'series', '2026', 'Action & Adventure', 'TV-14', 5.0, 'Best friends Debbie and Judith are forced on the run when Debbie discovers Judith isn''t a forensic accountant, she''s an international assassin! With a mysterious figure chasing them, and Debbie''s husband involved in something deeply corrupt, it''s a race against time and a road trip across Europe to untangle the truth and stay alive.', '/assets/posters/tv_241882.jpg', '/assets/backdrops/tv_241882.jpg', '/assets/video/clip_35079542.mp4', 42, NULL, 'en'),
  (31, 'Cape Fear', 'series', '2026', 'Drama', 'TV-14', 7.1, 'When convicted murderer Max Cady is released from prison, he begins infiltrating the family of the married attorneys who helped put him behind bars.', '/assets/posters/tv_277439.jpg', '/assets/backdrops/tv_277439.jpg', '/assets/video/clip_30070091.mp4', 42, NULL, 'en'),
  (32, 'Star Wars: The Mandalorian and Grogu | A Special Look', 'series', '2026', 'Documentary', 'TV-14', 8.3, 'Get ready for "Star Wars: The Mandalorian and Grogu | A Special Look," only in theaters.', '/assets/posters/tv_321564.jpg', '/assets/backdrops/tv_321564.jpg', '/assets/video/clip_18972999.mp4', 42, NULL, 'en'),
  (33, 'Mushoku Tensei: Jobless Reincarnation', 'series', '2021', 'Action & Adventure', 'TV-14', 8.5, 'When a 34-year-old underachiever gets run over by a truck, his story doesn''t end there. Reincarnated in a new world as an infant, Rudy will seize every opportunity to live the life he''s always wanted. Armed with new friends, some freshly acquired magical abilities, and the courage to do the things he''s always dreamed of, he''s embarking on an epic adventure—with all of his past experience intact!', '/assets/posters/tv_94664.jpg', '/assets/backdrops/tv_94664.jpg', '/assets/video/clip_27152549.mp4', 42, NULL, 'ja'),
  (34, 'FROM', 'series', '2022', 'Mystery', 'TV-14', 8.5, 'Unravel the mystery of a nightmarish town in middle America that traps all those who enter. As the unwilling residents fight to keep a sense of normalcy and search for a way out, they must also survive the threats of the surrounding forest – including the terrifying creatures that come out when the sun goes down.', '/assets/posters/tv_124364.jpg', '/assets/backdrops/tv_124364.jpg', '/assets/video/clip_27152555.mp4', 42, 7, 'en'),
  (35, 'King of the Hill', 'series', '1997', 'Animation', 'TV-14', 7.4, 'Set in Texas, this animated series follows the life of propane salesman Hank Hill, who lives with his overly confident substitute Spanish teacher wife Peggy, wannabe comedian son Bobby, and naive niece Luanne. Hank has conservative views about God, family, and country, but his values and ethics are often challenged by the situations he, his family, and his beer-drinking neighbors/buddies find themselves in.', '/assets/posters/tv_2122.jpg', '/assets/backdrops/tv_2122.jpg', '/assets/video/clip_30997958.mp4', 42, NULL, 'en'),
  (36, 'Stranger Things', 'series', '2016', 'Action & Adventure', 'TV-14', 8.6, 'When a young boy vanishes, a small town uncovers a mystery involving secret experiments, terrifying supernatural forces, and one strange little girl.', '/assets/posters/tv_66732.jpg', '/assets/backdrops/tv_66732.jpg', '/assets/video/clip_35079542.mp4', 42, 3, 'en'),
  (37, 'Overdo', 'series', '2026', 'Drama', 'TV-14', 9.0, 'In Republican Shanghai, Murong Qingyi, a warlord’s son swapped at birth, endures years of torment. His life changes when Ren Susu saves him, but tragedy strikes her family because of it. Years later, love sparks between them, but Ren Susu fakes her death to save another, leaving Qingyi heartbroken. Three years on, she returns as his future sister-in-law. Love, hate, betrayal, and old wounds resurface. As war looms, the two must defy fate together, but can love survive a nation’s fall?', '/assets/posters/tv_289139.jpg', '/assets/backdrops/tv_289139.jpg', '/assets/video/clip_30070091.mp4', 42, NULL, 'zh'),
  (38, 'X-Men ''97', 'series', '2024', 'Animation', 'TV-14', 8.6, 'The X-Men, a band of mutants who use their uncanny gifts to protect a world that hates and fears them, are challenged like never before, forced to face a dangerous and unexpected new future.', '/assets/posters/tv_138502.jpg', '/assets/backdrops/tv_138502.jpg', '/assets/video/clip_18972999.mp4', 42, 8, 'en'),
  (39, 'The Westies', 'series', '2026', 'Drama', 'TV-14', 6.1, 'As the Javits Center construction project ignites a battle for profit in early 1980s Hell''s Kitchen, a generational rift threatens the uneasy peace between violent Irish gang the Westies and the Mafia, and draws FBI heat.', '/assets/posters/tv_286709.jpg', '/assets/backdrops/tv_286709.jpg', '/assets/video/clip_27152549.mp4', 42, NULL, 'en'),
  (40, 'THE GHOST IN THE SHELL', 'series', '2026', 'Animation', 'TV-14', 8.3, '2029, a near-future Japan. The full cyborg Motoko Kusanagi envisions a task force that preemptively strikes emerging threats. She and her team are scouted by Daisuke Aramaki as Public Security Section 9, AKA the "Shell Squad." An international conspiracy hints at a hacker known as The "Puppet Master." What fate awaits Kusanagi? What is the hacker''s endgame? A new era of cyberpunk action begins!', '/assets/posters/tv_255358.jpg', '/assets/backdrops/tv_255358.jpg', '/assets/video/clip_27152555.mp4', 42, NULL, 'ja'),
  (41, 'Supergirl', 'movie', '2026', 'Action', 'TV-14', 6.1, 'When an unexpected and ruthless adversary strikes too close to home, Kara Zor-El, aka Supergirl, reluctantly joins forces with an unlikely companion on an epic, interstellar journey of vengeance and justice.', '/assets/posters/movie_1081003.jpg', '/assets/backdrops/movie_1081003.jpg', '/assets/video/clip_30997958.mp4', 103, 10, 'en'),
  (42, 'Project Hail Mary', 'movie', '2026', 'Science Fiction', 'TV-14', 8.7, 'Science teacher Ryland Grace wakes up on a spaceship light years from home with no recollection of who he is or how he got there. As his memory returns, he begins to uncover his mission: solve the riddle of the mysterious substance causing the sun to die out. He must call on his scientific knowledge and unorthodox ideas to save everything on Earth from extinction.', '/assets/posters/movie_687163.jpg', '/assets/backdrops/movie_687163.jpg', '/assets/video/clip_35079542.mp4', 110, 5, 'en'),
  (43, 'Desire', 'movie', '2026', 'Mystery', 'TV-14', 6.8, 'Lucero’s life appears immaculate: a wealthy household, a devoted husband, and two children who embody the promise of a perfect family. Yet beneath this surface simmers a quiet dissatisfaction. When Matías, a young swimming coach hired by her husband, enters their lives, Lucero finds herself pulled into a risky and consuming relationship. As secrecy, desire, and jealousy tighten their grip, the boundaries within the family begin to collapse, placing mother and daughter in a dangerous emotional triangle that threatens to shatter everything Lucero has built.', '/assets/posters/movie_1668364.jpg', '/assets/backdrops/movie_1668364.jpg', '/assets/video/clip_30070091.mp4', 117, NULL, 'es'),
  (44, 'Passenger', 'movie', '2026', 'Horror', 'TV-14', 7.3, 'After a young couple witnesses a gruesome highway accident, they soon realize they did not leave the crash scene alone, as a demonic presence called the Passenger that won''t stop until it claims them both turns their van life adventure into a nightmare.', '/assets/posters/movie_1368314.jpg', '/assets/backdrops/movie_1368314.jpg', '/assets/video/clip_18972999.mp4', 124, NULL, 'en'),
  (45, 'Affair at the Nuns'' Temple: Paradise Sex', 'movie', '1998', '', 'TV-14', 1.7, 'Japanese nunsplitation movie from 1998', '/assets/posters/movie_261639.jpg', '/assets/posters/movie_261639.jpg', '/assets/video/clip_27152549.mp4', 96, NULL, 'ja'),
  (46, 'Your Heart Will Be Broken', 'movie', '2026', 'Romance', 'TV-14', 7.1, 'High school student Polina is saved from bullying at her new school and makes a deal with the main bully Bars: he must pretend to be her boyfriend and protect her, and she must do everything he says. During this game, the couple develops real feelings, but her family and classmates have reasons to separate the lovers.', '/assets/posters/movie_1523145.jpg', '/assets/backdrops/movie_1523145.jpg', '/assets/video/clip_27152555.mp4', 103, NULL, 'ru'),
  (47, 'Deep Water', 'movie', '2026', 'Horror', 'TV-14', 7.5, 'A group of international passengers on a flight from Los Angeles to Shanghai is forced to make an emergency landing in shark-infested waters. The terrified group is forced to work together and overcome their differences if they hope to escape their sinking plane and the frenzy of sharks drawn to the wreckage.', '/assets/posters/movie_1127384.jpg', '/assets/backdrops/movie_1127384.jpg', '/assets/video/clip_30997958.mp4', 110, NULL, 'en'),
  (48, 'Michael', 'movie', '2026', 'Music', 'TV-14', 8.7, 'The story of Michael Jackson, one of the most influential artists the world has ever known, and his life beyond the music. His journey from the discovery of his extraordinary talent as the lead of the Jackson Five, to the visionary artist whose creative ambition fueled a relentless pursuit to become the biggest entertainer in the world, highlighting both his life off-stage and some of the most iconic performances from his early solo career.', '/assets/posters/movie_936075.jpg', '/assets/backdrops/movie_936075.jpg', '/assets/video/clip_35079542.mp4', 117, NULL, 'en'),
  (49, 'Lecture Room', 'series', '2001', 'Talk', 'TV-14', 7.0, '', '/assets/posters/tv_237020.jpg', '/assets/backdrops/tv_237020.jpg', '/assets/video/clip_30070091.mp4', 42, NULL, 'zh'),
  (50, 'Binnelanders', 'series', '2005', 'Soap', 'TV-14', 5.5, 'A South African Afrikaans soap opera. It is set in and around the fictional private hospital, Binneland Kliniek, in Pretoria, and the storyline follows the trials, trauma and tribulations of the staff and patients of the hospital.', '/assets/posters/tv_206559.jpg', '/assets/backdrops/tv_206559.jpg', '/assets/video/clip_18972999.mp4', 42, NULL, 'af'),
  (51, '7de Laan', 'series', '2000', 'Soap', 'TV-14', 8.3, '7de Laan is an extraordinary microcosm where good and bad, evil and wholesome characters find themselves forming part of a wholesome community where no matter what – everyone counts and everyone cares…', '/assets/posters/tv_17887.jpg', '/assets/backdrops/tv_17887.jpg', '/assets/video/clip_27152549.mp4', 42, NULL, 'af'),
  (52, 'C.I.D.', 'series', '1998', 'Action & Adventure', 'TV-14', 5.7, 'A team of dedicated men and women in the Crime Investigation Department will risk everything to solve Mumbai''s toughest, most complicated crimes.', '/assets/posters/tv_15226.jpg', '/assets/backdrops/tv_15226.jpg', '/assets/video/clip_27152555.mp4', 42, NULL, 'hi'),
  (53, 'Late Show with David Letterman', 'series', '1993', 'Talk', 'TV-14', 6.4, 'David Letterman uses mature humor to appeal to his audience in this weeknight series, which gets its music from a house band led by Paul Shaffer. Among the show''s most-famous segments are the Top Ten List and Stupid Pet Tricks, the latter of which subsequently led to an additional recurring segment called Stupid Human Tricks.', '/assets/posters/tv_498.jpg', '/assets/backdrops/tv_498.jpg', '/assets/video/clip_30997958.mp4', 42, NULL, 'en'),
  (54, 'The Tonight Show Starring Johnny Carson', 'series', '1962', 'Talk', 'TV-14', 7.5, 'The Tonight Show Starring Johnny Carson is a talk show hosted by Johnny Carson under The Tonight Show franchise from 1962 to 1992. It originally aired during late-night. For its first ten years, Carson''s Tonight Show was based in New York City with occasional trips to Burbank, California; in May 1972, the show moved permanently to Burbank, California. In 2002, The Tonight Show Starring Johnny Carson was ranked #12 on TV Guide''s 50 Greatest TV Shows of All Time.', '/assets/posters/tv_2261.jpg', '/assets/backdrops/tv_2261.jpg', '/assets/video/clip_35079542.mp4', 42, NULL, 'en'),
  (55, 'Egoli: Place of Gold', 'series', '1992', 'Soap', 'TV-14', 7.2, 'A South African television soap opera created by Franz Marx which revolves around the daily ups, downs, trials and tribulations of a handful of families in and around Johannesburg (which is often referred to as eGoli - the City of Gold)', '/assets/posters/tv_12415.jpg', '/assets/backdrops/tv_12415.jpg', '/assets/video/clip_30070091.mp4', 42, NULL, 'af'),
  (56, 'Jeopardy!', 'series', '1984', 'Reality', 'TV-14', 6.9, 'America''s favorite quiz show where contestants are presented with general knowledge clues in the form of answers, and must phrase their responses in question form.', '/assets/posters/tv_2912.jpg', '/assets/backdrops/tv_2912.jpg', '/assets/video/clip_18972999.mp4', 42, NULL, 'en'),
  (57, 'The Daily Show', 'series', '1996', 'News', 'TV-14', 6.4, 'The World''s Fakest News Team tackle the biggest stories in news, politics and pop culture.', '/assets/posters/tv_2224.jpg', '/assets/backdrops/tv_2224.jpg', '/assets/video/clip_27152549.mp4', 42, NULL, 'en'),
  (58, 'Law & Order: Special Victims Unit', 'series', '1999', 'Crime', 'TV-14', 8.0, 'In the criminal justice system, sexually-based offenses are considered especially heinous. In New York City, the dedicated detectives who investigate these vicious felonies are members of an elite squad known as the Special Victims Unit. These are their stories.', '/assets/posters/tv_2734.jpg', '/assets/backdrops/tv_2734.jpg', '/assets/video/clip_27152555.mp4', 42, NULL, 'en'),
  (59, 'The Late Show with Stephen Colbert', 'series', '2015', 'Comedy', 'TV-14', 6.1, 'Stephen Colbert brings his signature satire and comedy to The Late Show with Stephen Colbert, the #1 show in late night, where he talks with an eclectic mix of guests about what is new and relevant in the worlds of politics, entertainment, business, music, technology, and more. Featuring bandleader Jon Batiste with his band Stay Human, the Emmy Award-nominated show is broadcast from the historic Ed Sullivan Theater.', '/assets/posters/tv_63770.jpg', '/assets/backdrops/tv_63770.jpg', '/assets/video/clip_30997958.mp4', 42, NULL, 'en'),
  (60, 'Rote Rosen', 'series', '2006', 'Soap', 'TV-14', 3.0, 'Rote Rosen is a German telenovela produced by Studio Hamburg Serienwerft Lüneburg and broadcast by Das Erste since November 6, 2006. The show is a complex telenovela, who tells one love story every season about women in their forties.', '/assets/posters/tv_27181.jpg', '/assets/backdrops/tv_27181.jpg', '/assets/video/clip_35079542.mp4', 42, NULL, 'de');

